parameters.jsCode:
// Contrato de entrada (Lab 02) + clave de idempotencia (hash polinomial determinista).
let q = query;
if (typeof q === 'string') { try { q = JSON.parse(q); } catch (e) { q = {}; } }
q = q || {};
const errores = [];
const hoy = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Lima' });

let tel = String(q.telefono || '').replace(/[\s\-()]/g, '');
if (/^9\d{8}$/.test(tel)) tel = '+51' + tel;
if (/^51\d{9}$/.test(tel)) tel = '+' + tel;
if (!/^\+\d{10,15}$/.test(tel)) errores.push('telefono: se necesita un celular válido (ej. 987 654 321)');

let placa = String(q.placa || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
if (!/^[A-Z0-9]{6,7}$/.test(placa)) errores.push('placa: debe tener 6 a 7 caracteres (ej. ABC-123)');
else placa = placa.slice(0, 3) + '-' + placa.slice(3);

const vehiculo = String(q.vehiculo || '').trim();
if (!vehiculo) errores.push('vehiculo: falta marca, modelo y año');

const tipo = String(q.tipo_servicio || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
if (!['preventivo', 'correctivo'].includes(tipo)) errores.push('tipo_servicio: debe ser preventivo o correctivo');

const fecha = String(q.fecha_deseada || '').trim().slice(0, 10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) errores.push('fecha_deseada: falta una fecha válida (AAAA-MM-DD)');
else if (fecha < hoy) errores.push('fecha_deseada: no puede ser anterior a hoy (' + hoy + ')');

const desc = String(q.descripcion_falla || '').trim();
if (!desc) errores.push('descripcion_falla: falta el servicio o síntoma');
if (desc.length > 500) errores.push('descripcion_falla: máximo 500 caracteres');

let km = Number(q.kilometraje);
if (!Number.isFinite(km) || km < 0) km = 0;

// Clave de negocio: teléfono | placa | servicio | fecha (sin marcas de tiempo ni IDs de plataforma)
const material = [tel, placa, tipo, fecha].join('|').toLowerCase();
let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
for (let i = 0; i < material.length; i++) {
  const ch = material.charCodeAt(i);
  h1 = Math.imul(h1 ^ ch, 2654435761);
  h2 = Math.imul(h2 ^ ch, 1597334677);
}
h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
const clave = 'MV-' + (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');

return JSON.stringify({
  valido: errores.length === 0,
  errores,
  clave: errores.length === 0 ? clave : '',
  datos: { telefono: tel, placa, vehiculo, kilometraje: Math.round(km), tipo_servicio: tipo, fecha_deseada: fecha, descripcion_falla: desc }
});

// Aritmética determinista: el LLM elige conceptos, este código calcula.
let q = query;
if (typeof q === 'string') { try { q = JSON.parse(q); } catch (e) { q = {}; } }
const items = ((q && q.items) || []).map(i => {
  const cantidad = Math.max(1, Math.round(Number(i.cantidad) || 1));
  const precio = Number(i.precio_unitario) || 0;
  return {
    codigo: i.codigo, concepto: i.concepto, tipo: i.tipo, cantidad, precio_unitario: precio,
    subtotal: Math.round(cantidad * precio * 100) / 100,
    bajo_pedido: i.tipo === 'repuesto' && Number(i.stock) < cantidad
  };
});
const total = Math.round(items.reduce((s, i) => s + i.subtotal, 0) * 100) / 100;
return JSON.stringify({ items, total, repuestos_bajo_pedido: items.filter(i => i.bajo_pedido).map(i => i.concepto) });
